@RestController
@RequestMapping("/api/products")
public class ProductController {

    private final ProductService productService;

    public ProductController(ProductService productService) {
        this.productService = productService;
    }

    @PostMapping
    public ResponseEntity<Product> createProduct(@RequestBody ProductRequest request) {
        // Spring already deserialized JSON to ProductRequest object
        var product = productService.create(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(product);
    }
}

record ProductRequest(String name, BigDecimal price, String category) {}
// Client sends: {"name":"Laptop","price":999.99,"category":"Electronics"}
// Spring converts it to ProductRequest instance automatically

// Old style with @Controller - need @ResponseBody on each method
@Controller
@RequestMapping("/api/users")
public class OldStyleController {
    @GetMapping("/{id}")
    @ResponseBody  // Must add this to return JSON
    public User getUser(@PathVariable Long id) {
        return new User(id, "Alice", "alice@example.com");
    }
}

// Modern style with @RestController - automatic @ResponseBody
@RestController
@RequestMapping("/api/users")
public class UserController {
    @GetMapping("/{id}")
    public User getUser(@PathVariable Long id) {
        // No @ResponseBody needed - returns JSON automatically
        return new User(id, "Alice", "alice@example.com");
    }
}

record User(Long id, String name, String email) {}

import jakarta.validation.Valid;
import jakarta.validation.constraints.*;

@RestController
@RequestMapping("/api/products")
public class ProductController {

    private final ProductService productService;

    public ProductController(ProductService productService) {
        this.productService = productService;
    }

    @PostMapping
    public ResponseEntity<Product> createProduct(@Valid @RequestBody ProductRequest request) {
        // If validation fails, this method never runs - Spring returns 400 automatically
        var product = productService.create(request);
        return ResponseEntity.status(HttpStatus.CREATED).body(product);
    }
}

record ProductRequest(
    @NotBlank(message = "Product name is required") String name,
    @Positive(message = "Price must be positive") BigDecimal price,
    @Size(min = 2, max = 50) String category
) {}

@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService orderService;

    public OrderController(OrderService orderService) {
        this.orderService = orderService;
    }

    @GetMapping
    public List<Order> getOrders(
            @RequestHeader("X-User-Id") Long userId,
            @RequestHeader(value = "X-Trace-Id", required = false, defaultValue = "unknown") String traceId,
            @CookieValue(value = "sessionId", required = false) String sessionId) {
        // userId is mandatory - Spring returns 400 if header missing
        // traceId defaults to "unknown" if header absent
        // sessionId is optional - null if cookie not present
        return orderService.findByUser(userId, traceId, sessionId);
    }
}

// BAD: Returning entity directly - exposes all fields, risks lazy loading errors
@RestController
@RequestMapping("/api/users")
public class BadUserController {
    @GetMapping("/{id}")
    public User getUser(@PathVariable Long id) {
        return userRepository.findById(id).orElseThrow();
        // Exposes password field, internal audit fields, lazy-loaded orders collection
    }
}

// GOOD: Using DTO - explicit API contract, safe, no lazy loading issues
@RestController
@RequestMapping("/api/users")
public class UserController {
    @GetMapping("/{id}")
    public UserResponse getUser(@PathVariable Long id) {
        var user = userRepository.findById(id).orElseThrow();
        return new UserResponse(user.getId(), user.getName(), user.getEmail());
        // Only exposes what the API needs - no password, no internal fields
    }
}

record UserResponse(Long id, String name, String email) {}
